function villageRace(v){if(v.culture)return v.culture;const counts={};for(const e of humans())if(e.village===v.id)counts[e.race]=(counts[e.race]||0)+1;return Object.keys(counts).sort((a,b)=>counts[b]-counts[a])[0]||'human';}
function kingdomRace(k){const people=members(k),counts={};for(const e of people)counts[e.race]=(counts[e.race]||0)+1;return Object.keys(counts).sort((a,b)=>counts[b]-counts[a])[0]||'human';}
function mindFor(e){let m=minds.get(e);if(!m){m={type:'idle',goal:null,until:0,navAt:0,stuck:0,lastX:e.x,lastY:e.y,exploreUntil:0};minds.set(e,m);}return m;}
function passFor(e,x,y){return inside(x,y)&&grid[idx(x,y)].t!==4&&(grid[idx(x,y)].t!==0||e.sailing);}
function clearRoute(e,to){const len=Math.hypot(to.x-e.x,to.y-e.y),n=Math.max(1,Math.ceil(len*4));for(let k=1;k<=n;k++)if(!passFor(e,e.x+(to.x-e.x)*k/n,e.y+(to.y-e.y)*k/n))return false;return true;}
const tilePathStep=pathStep;
pathStep=function(e,goal,allowWater){const next=tilePathStep(e,goal,allowWater);if(!next)return idx(e.x,e.y)===idx(goal.x,goal.y)?{x:goal.x,y:goal.y}:null;const field=routeFields.get(terrainEpoch+':'+idx(goal.x,goal.y)+':'+Number(allowWater));if(!field)return next;const can=i=>grid[i].t!==4&&(allowWater||grid[i].t!==0);let node=idx(next.x,next.y),best=next;for(let step=0;step<5&&node!==idx(goal.x,goal.y);step++){const x=node%W,y=Math.floor(node/W),options=[x>0?node-1:-1,x<W-1?node+1:-1,y>0?node-W:-1,y<H-1?node+W:-1].filter(n=>n>=0&&can(n)&&field.distance[n]>=0&&field.distance[n]<field.distance[node]);if(!options.length)break;node=options[0];const target={x:node%W+.5,y:Math.floor(node/W)+.5},water=e.sailing;e.sailing=!!allowWater;const clear=clearRoute(e,target);e.sailing=water;if(!clear)break;best=target;}return best;};
function go(e,goal,type,seconds=6){const m=mindFor(e);if(!goal||!inside(goal.x,goal.y)){stop(e,type);return false;}if(m.type!==type||!m.goal||Math.hypot(m.goal.x-goal.x,m.goal.y-goal.y)>.6){m.goal={x:goal.x,y:goal.y};m.type=type;m.until=simTime+seconds;m.navAt=0;}return navigate(e);}
function stop(e,type='idle'){const m=mindFor(e);m.type=type;m.goal=null;m.until=simTime+1;e.tx=e.x;e.ty=e.y;}
function navigate(e){const m=mindFor(e);if(!m.goal)return false;if(Math.hypot(e.x-m.goal.x,e.y-m.goal.y)<.3){stop(e,m.type);return true;}if(simTime<m.navAt&&Math.hypot(e.tx-e.x,e.ty-e.y)>.6)return true;m.navAt=simTime+.35;const target=clearRoute(e,m.goal)?m.goal:pathStep(e,m.goal,e.sailing);if(!target){m.goal=null;e.tx=e.x;e.ty=e.y;return false;}e.tx=target.x;e.ty=target.y;return true;}
function indexResidents(){localCells=new Map();for(const e of entities){const key=Math.floor(e.x/3)+':'+Math.floor(e.y/3);if(!localCells.has(key))localCells.set(key,[]);localCells.get(key).push(e);}}
function around(e,r=5,predicate=null){const result=[],d=Math.ceil(r/3),cx=Math.floor(e.x/3),cy=Math.floor(e.y/3);for(let y=cy-d;y<=cy+d;y++)for(let x=cx-d;x<=cx+d;x++)for(const p of localCells.get(x+':'+y)||[])if(p.id!==e.id&&p.hp>0&&(!predicate||predicate(p))&&Math.hypot(p.x-e.x,p.y-e.y)<r)result.push(p);return result;}
function nearestTile(e,test,r=10){const candidates=[];for(let y=Math.max(0,Math.floor(e.y-r));y<Math.min(H,e.y+r+1);y++)for(let x=Math.max(0,Math.floor(e.x-r));x<Math.min(W,e.x+r+1);x++){const t=grid[idx(x,y)];if(!walkable(x,y)||!test(t,x,y))continue;const d=(x+.5-e.x)**2+(y+.5-e.y)**2;if(candidates.length<8||d<candidates[candidates.length-1].d){candidates.push({x:x+.5,y:y+.5,d});candidates.sort((a,b)=>a.d-b.d);if(candidates.length>8)candidates.pop();}}for(const goal of candidates)if(clearRoute(e,goal)||pathStep(e,goal,e.sailing))return goal;return null;}
function safeDirection(e,threat){const dx=e.x-threat.x,dy=e.y-threat.y,length=Math.hypot(dx,dy)||1;return findLand(e.x+dx/length*5,e.y+dy/length*5);}
function compatibleVillage(e){return villages.filter(v=>villageRace(v)===e.race).reduce((best,v)=>!best||Math.hypot(e.x-v.x,e.y-v.y)<Math.hypot(e.x-best.x,e.y-best.y)?v:best,null);}
nearestVillage=function(e,y){if(typeof e==='number')e={x:e,y};if(!e||!Number.isFinite(e.x)||!Number.isFinite(e.y))return null;return e.kind==='human'?compatibleVillage(e):villages.reduce((b,v)=>!b||Math.hypot(e.x-v.x,e.y-v.y)<Math.hypot(e.x-b.x,e.y-b.y)?v:b,null);};
function initializeMindState(){for(const v of villages){v.culture??=villageRace(v);v.water??=100;v.settledAt??=simTime;ensureVillageEconomy(v);}for(const e of humans()){ensureRoutine(e);e.thirst??=80;}indexResidents();}
function foundSettlement(group,parent=null){if(group.length<3||villages.length>=40||kingdoms.length>=95)return null;const leader=group.find(e=>e.age>=2);if(!leader)return null;const p=findLand(leader.x,leader.y);if(!p||villages.some(v=>Math.hypot(v.x-p.x,v.y-p.y)<(parent?14:7)))return null;const v={id:idCounter++,name:'Làng '+raceNames[leader.race]+' '+(villages.length+1),x:p.x,y:p.y,food:parent?35:25,wood:parent?8:6,level:1,color:parent?.color||{human:'#a4e4a4',elf:'#71c8b2',orc:'#e5a086',dwarf:'#d6b078',goblin:'#b4cd73',beastkin:'#c19ddb'}[leader.race],culture:leader.race,water:80,settledAt:simTime};if(parent){if(parent.food<65||parent.wood<18||parent.stock.stone<8)return null;parent.food-=35;parent.wood-=10;parent.stock.stone-=8;v.kingdom=parent.kingdom;v.devotion=parent.devotion;v.tech=Math.min(1,parent.tech);v.knowledge=0;v.temple=false;v.memory=[];}villages.push(v);houses.push({id:idCounter++,x:p.x,y:p.y,village:v.id,level:0,hp:100});for(const e of group){e.village=v.id;stop(e);}ensureVillageEconomy(v);initializeCivilization();remember(raceNames[leader.race]+' khai phá '+v.name+'.','civil');mapDirty=true;return v;}
function settleUnclaimed(){const handled=new Set();for(const e of humans())if(!e.village&&!handled.has(e.id)){const v=compatibleVillage(e);if(v&&Math.hypot(e.x-v.x,e.y-v.y)<16){e.village=v.id;continue;}const group=humans().filter(p=>!p.village&&p.race===e.race&&Math.hypot(p.x-e.x,p.y-e.y)<7);for(const p of group)handled.add(p.id);if(group.length>=3)foundSettlement(group);}}
function planResident(e){const m=mindFor(e),v=villages.find(v=>v.id===e.village),home=houses.filter(h=>h.village===e.village).reduce((b,h)=>!b||Math.hypot(h.x-e.x,h.y-e.y)<Math.hypot(b.x-e.x,b.y-e.y)?h:b,null);if(e.id===possessed)return;
 const myKing=kingdomOf(e),threat=(laws.predators||wars.length)?around(e,6,p=>p.kind==='wolf'&&laws.predators&&(typeof hungryPredator!=='function'||hungryPredator(p))||p.kind==='human'&&wars.length&&atWar(myKing,kingdomOf(p))).sort((a,b)=>Math.hypot(a.x-e.x,a.y-e.y)-Math.hypot(b.x-e.x,b.y-e.y))[0]:null;
 if(threat&&!e.soldier&&(e.hp<80||e.kind==='human')){e.sailing=false;go(e,safeDirection(e,threat),'flee',3);return;}
 if(e.hunger<45){e.sailing=false;if(v&&v.food>2)go(e,v,'food',10);else go(e,nearestTile(e,t=>t.food>3,12),'food',10);return;}
 if(e.thirst<35){e.sailing=false;const water=v&&v.water>0?v:nearestTile(e,(t,x,y)=>[[1,0],[-1,0],[0,1],[0,-1]].some(([dx,dy])=>inside(x+dx,y+dy)&&grid[idx(x+dx,y+dy)].t===0),16);go(e,water,'water',10);return;}
 if(e.soldier){const targets=humans().filter(p=>atWar(kingdomOf(e),kingdomOf(p))),enemy=targets.reduce((b,p)=>!b||Math.hypot(p.x-e.x,p.y-e.y)<Math.hypot(b.x-e.x,b.y-e.y)?p:b,null);e.sailing=!!(v?.tech>=2);if(enemy){if(Math.hypot(enemy.x-e.x,enemy.y-e.y)<=1.5)stop(e,'fight');else go(e,enemy,'fight',3);}return;}
 const weather=weatherAt(e.x,e.y);if(home&&['storm','snow'].includes(weather)&&e.talent!=='frost'){e.sailing=false;if(Math.hypot(home.x-e.x,home.y-e.y)>1.5)go(e,home,'shelter',15);else stop(e,'shelter');return;}
 if(['sleeping','resting'].includes(e.activity)){e.sailing=false;if(home&&Math.hypot(home.x-e.x,home.y-e.y)>1.1)go(e,{x:home.x+Math.cos(e.id)*.55,y:home.y+Math.sin(e.id)*.55},'home',20);else stop(e,'home');return;}
 if(m.type==='explore'&&m.goal&&simTime<m.until){navigate(e);return;}
 if(!v){if(m.goal&&simTime<m.until){navigate(e);return;}go(e,nearestTile(e,t=>t.food>5,10),'explore',20);return;}
 if(e.id%8===0&&v.tech>=1&&v.food>65&&members(v.kingdom).length>=10){e.sailing=v.tech>=2;if(m.type==='explore'&&m.goal&&simTime<m.until){navigate(e);return;}const angle=(e.id*.91+simTime*.012)%(Math.PI*2),p=findLand(v.x+Math.cos(angle)*22,v.y+Math.sin(angle)*22);if(p){go(e,p,'explore',45);return;}}
 e.sailing=false;if(m.workJob===e.job&&m.retryWork>simTime&&!m.goal)return;if(e.job==='miner'){if(e.cargo){go(e,v,'work',20);return;}const target=resourceTarget(e,v);if(target){if(Math.hypot(e.x-target.stand.x,e.y-target.stand.y)>1.3)go(e,target.stand,'work',20);else stop(e,'work');return;}}
 if(['farmer','lumberjack'].includes(e.job)){const wanted=t=>e.job==='lumberjack'?t.t===3:t.t===5;if(wanted(grid[idx(e.x,e.y)])){stop(e,'work');return;}if(m.type==='work'&&m.goal&&wanted(grid[idx(m.goal.x,m.goal.y)])){navigate(e);return;}const target=nearestTile(e,wanted,15);if(target){go(e,target,'work',20);return;}m.workJob=e.job;m.retryWork=simTime+5;stop(e,'work');return;}
 if(['builder','smith','merchant'].includes(e.job)){const kind={builder:'warehouse',smith:'forge',merchant:'market'}[e.job],b=buildings.find(b=>b.village===v.id&&b.kind===kind)||v;go(e,{x:b.x+.7*Math.cos(e.id),y:b.y+.7*Math.sin(e.id)},'work',15);return;}
 if(m.goal&&simTime<m.until){navigate(e);return;}if(simTime<m.until)return;go(e,findLand(e.x+Math.cos(e.id+simTime*.05)*4,e.y+Math.sin(e.id+simTime*.05)*4),'wander',10);}
function planAnimal(e){if(e.id===possessed)return;const m=mindFor(e);e.sailing=false;if(e.kind==='sheep'){const wolf=laws.predators?around(e,7).find(p=>p.kind==='wolf'):null;if(wolf){go(e,safeDirection(e,wolf),'flee',3);return;}if(e.hunger<80){const food=nearestTile(e,t=>t.food>2,9);if(food){go(e,food,'graze',10);return;}}}else if(e.kind==='wolf'&&laws.predators){const prey=around(e,13).filter(p=>p.kind==='sheep'||e.hunger<25&&p.kind==='human').reduce((b,p)=>!b||Math.hypot(p.x-e.x,p.y-e.y)<Math.hypot(b.x-e.x,b.y-e.y)?p:b,null);if(prey){if(Math.hypot(prey.x-e.x,prey.y-e.y)<1.2)stop(e,'hunt');else go(e,prey,'hunt',3);return;}}
 if(m.goal&&simTime<m.until){navigate(e);return;}if(simTime<m.until)return;const angle=e.id+simTime*.07;go(e,findLand(e.x+Math.cos(angle)*4,e.y+Math.sin(angle)*4),'wander',8);if(!m.goal)m.until=simTime+2;}
steerWorkers=function(){indexResidents();for(const e of entities)if(e.hp>0){if(e.kind==='human')planResident(e);else planAnimal(e);}};
const naturalAdvance=advanceCreature;
advanceCreature=function(e,dt){const m=mindFor(e);if(m.goal&&Math.hypot(e.tx-e.x,e.ty-e.y)<.8)navigate(e);const before={x:e.x,y:e.y};naturalAdvance(e,dt);const movement=motionFor(e);if(Math.abs(movement.vx)>.08)movement.facing=movement.vx<0?-1:1;if(m.goal){const delta=Math.hypot(e.x-before.x,e.y-before.y);m.stuck=delta<.0001?m.stuck+dt:0;if(m.stuck>2){m.navAt=0;m.goal=null;m.until=simTime+1;e.tx=e.x;e.ty=e.y;m.stuck=0;}}};
function spriteFlip(e){const facing=motionFor(e).facing||1,nativeFacing=e.kind==='human'?1:-1;return facing===nativeFacing?1:-1;}
function drawCreature(e,bob){const m=motionFor(e);ctx.save();ctx.translate(e.x,e.y);ctx.scale(spriteFlip(e),1);const lean=Math.sin(m.steps*7+e.id)*(typeof animationPose==='function'?animationPose(e).walk*.012:Math.min(.035,Math.hypot(m.vx,m.vy)*.02));ctx.rotate(lean);ctx.translate(-e.x,-e.y);if(e.kind==='human')drawPerson(e,bob);else drawSprite(e.kind==='sheep'?6:7,e.x,e.y+bob,e.kind==='wolf'?1.6:1.7);ctx.restore();}
function techRequirement(v){const goal=techGoals[v.tech];if(!goal)return 'Đã đạt Tri thức';const housesCount=houses.filter(h=>h.village===v.id).length,farm=grid.some((t,i)=>t.t===5&&Math.hypot(i%W-v.x,Math.floor(i/W)-v.y)<10);return [v.food<goal.food?'Cần '+goal.food+' lương thực':'',housesCount<goal.houses?'Cần '+goal.houses+' nhà':'',goal.farm&&!farm?'Cần ruộng lúa':'',goal.kind&&!hasBuilding(v,goal.kind)?'Cần '+buildingDefs[goal.kind].name:''].filter(Boolean).join(' · ')||'Đủ điều kiện, đang tích lũy tri thức';}
civilizationStep=function(dt){initializeCivilization();for(const v of villages){const people=humans().filter(e=>e.village===v.id);if(!people.length)continue;const wisdom=people.filter(e=>e.traits.includes('wise')||e.talent==='sage').length,stable=v.food>people.length*2&&houses.some(h=>h.village===v.id)&&v.water>0;
 v.knowledge=Math.min(2000,v.knowledge+dt*(people.length*.002+wisdom*.004+(hasBuilding(v,'workshop')?.03:0))*(stable?1:.2));if(v.tech<4&&v.knowledge>=[30,110,260,520][v.tech]&&techRequirement(v).startsWith('Đủ')){v.tech++;remember(v.name+' bước vào thời '+techNames[v.tech]+'.','civil');}
 v.devotion=limit(v.devotion+(v.temple?.02:-.001)*dt,0,100);divine.faith=Math.min(99999,divine.faith+dt*people.length*v.devotion/500*(v.temple?2:1));const k=kingdoms.find(k=>k.id===v.kingdom);if(k)k.treasury=Math.min(99999,k.treasury+people.length*.01*dt);for(const e of people)e.devotion=v.devotion;
 v.water=Math.min(200,v.water+dt*(hasBuilding(v,'well')?.6:['rain','storm'].includes(weatherAt(v.x,v.y))?.15:.015));if(v.food<people.length*4)v.focus='farming';else if(wars.some(w=>[w.a,w.b].includes(v.kingdom)))v.focus='mining';else v.focus='balanced';
 }
 if(laws.disease)for(const e of humans().filter(e=>e.plague>0))for(const p of around(e,1.5))if(p.kind==='human'&&p.plague===0&&random()<.06)p.plague=25;
 electKings();if($('kingdom-dialog').open)renderKingdoms();if($('god-dialog').open)renderPrayers();};
function prepareSettlement(v){const people=humans().filter(e=>e.village===v.id),farmland=grid.some((t,i)=>t.t===5&&Math.hypot(i%W-v.x,Math.floor(i/W)-v.y)<10);if(typeof planFarmExpansion==='function')planFarmExpansion(v);else{if(!farmland&&people.some(e=>e.job==='farmer')&&v.wood>=2){let planted=0;for(let y=Math.floor(v.y-4);y<=v.y+4;y++)for(let x=Math.floor(v.x-4);x<=v.x+4;x++)if(planted<6&&inside(x,y)&&grid[idx(x,y)].t===1&&houses.every(h=>Math.hypot(h.x-x,h.y-y)>1.7)){Object.assign(grid[idx(x,y)],{t:5,obj:11,food:25});planted++;}if(planted){v.wood-=2;mapDirty=true;remember(v.name+' khai khẩn ruộng lúa.','civil');}}}
 if(v.food>65&&v.tech>=1&&people.length>=12){const candidates=people.filter(e=>!e.soldier&&e.age>=2&&e.id!==possessed),scout=candidates.find(e=>Math.hypot(e.x-v.x,e.y-v.y)>18);if(scout){const group=candidates.filter(e=>Math.hypot(e.x-scout.x,e.y-scout.y)<8).slice(0,4);if(group.length<3){for(const follower of candidates.filter(e=>e.id!==scout.id).slice(0,3)){follower.sailing=v.tech>=2;go(follower,scout,'explore',30);}}else foundSettlement(group,v);}}
}
function hostilityChance(a,b){const different=kingdomRace(a)!==kingdomRace(b);return different?Math.min(.9,.4+(aggression[kingdomRace(a)]+aggression[kingdomRace(b)])*.3):.07;}
function diplomaticStep(){if(!laws.war)return;for(const w of [...wars]){const a=members(w.a),b=members(w.b);if(laws.autoWar&&(simTime-w.started>180&&w.losses>=6||a.length<4||b.length<4))setDiplomacy(w.a,w.b,'peace');}if(!laws.autoWar||simTime<90)return;const active=kingdoms.filter(k=>members(k.id).length>=6);for(let i=0;i<active.length;i++)for(let j=i+1;j<active.length;j++){const a=active[i],b=active[j],rel=relations[pairKey(a.id,b.id)];if(atWar(a.id,b.id)||rel?.truceUntil>simTime||wars.filter(w=>[w.a,w.b].includes(a.id)).length>=2||wars.filter(w=>[w.a,w.b].includes(b.id)).length>=2)continue;const landA=villages.filter(v=>v.kingdom===a.id),landB=villages.filter(v=>v.kingdom===b.id),border=landA.find(x=>landB.some(y=>Math.hypot(x.x-y.x,x.y-y.y)<38));if(!border)continue;const target=landB.find(y=>Math.hypot(border.x-y.x,border.y-y.y)<38),scout={x:border.x,y:border.y,sailing:border.tech>=2};if(!pathStep(scout,target,scout.sailing))continue;if(random()<hostilityChance(a.id,b.id))setDiplomacy(a.id,b.id,'war');}}
setDiplomacy=function(a,b,state){mindOld.setDiplomacy(a,b,state);relations[pairKey(Number(a),Number(b))]={truceUntil:state==='peace'?simTime+300:0};};
electKings=function(){for(const k of kingdoms){const people=members(k.id);if(people.some(e=>e.id===k.king))continue;const previous=k.king,candidates=people.filter(e=>e.age>=(typeof lifeFor==='function'?16:2)).sort((a,b)=>((b.traits.includes('wise')?25:0)+(b.destiny?.chosen?15:0)+b.hp*.1+b.age+b.kills*2)-((a.traits.includes('wise')?25:0)+(a.destiny?.chosen?15:0)+a.hp*.1+a.age+a.kills*2));k.king=candidates[0]?.id||null;if(k.king){k.royalLine.push(k.king);k.royalLine=k.royalLine.slice(-20);remember(candidates[0].name+(previous?' kế vị':' được chọn làm vua của')+' '+k.name+'.','civil');}}};
function survivalStep(dt){initializeMindState();settleUnclaimed();for(const e of humans()){const v=villages.find(v=>v.id===e.village);e.thirst=Math.max(0,e.thirst-dt*(e.activity==='sleeping'?.012:.045));if(e.thirst<70&&v&&v.water>0&&Math.hypot(e.x-v.x,e.y-v.y)<3){const drink=Math.min(v.water,dt*.7);v.water-=drink;e.thirst=Math.min(100,e.thirst+drink*10);}else if(e.thirst<70&&inside(e.x,e.y)&&[[1,0],[-1,0],[0,1],[0,-1]].some(([x,y])=>inside(e.x+x,e.y+y)&&grid[idx(e.x+x,e.y+y)].t===0))e.thirst=Math.min(100,e.thirst+dt*5);if(e.thirst<=0)damage(e,dt*.4);if((typeof wantsMeal==='function'?wantsMeal(e):e.hunger<50)&&v&&v.food>0&&Math.hypot(e.x-v.x,e.y-v.y)<3){const meal=Math.min(v.food,dt*.6);v.food-=meal;e.hunger=Math.min(100,e.hunger+meal*10);}}steerWorkers();}
// Preserve fire, growth and combat, then give one brain the final navigation decision.
ecology=function(){mindOld.ecology();survivalStep(1);};
simulate=function(dt){mindOld.simulate(dt);diplomacyTick+=dt;expansionTick+=dt;mindTick+=dt;if(mindTick>=1){mindTick%=1;indexResidents();}if(diplomacyTick>=90){diplomacyTick%=90;diplomaticStep();}if(expansionTick>=20){expansionTick%=20;for(const v of [...villages])prepareSettlement(v);}};
function resetMinds(){minds=new WeakMap();mindTick=diplomacyTick=expansionTick=0;localCells.clear();relations={};initializeMindState();}
newWorld=function(...args){mindOld.newWorld(...args);for(const [i,v] of villages.entries()){v.culture=['human','elf','orc'][i%3];for(const e of humans().filter(e=>e.village===v.id)){e.race=v.culture;e.traits=[e.race==='elf'?'longlife':e.race==='orc'?'strong':'wise'];}}laws.autoWar=true;resetMinds();syncLawControls();renderKingdoms();steerWorkers();};
applyTool=function(...args){const before=new Set(entities.map(e=>e.id));mindOld.applyTool(...args);for(const e of humans())if(!before.has(e.id)){e.thirst=80;const v=villages.find(v=>v.id===e.village);if(v&&villageRace(v)!==e.race)e.village=null;}settleUnclaimed();initializeMindState();steerWorkers();};
showSelection=function(id){mindOld.showSelection(id);const e=humans().find(e=>e.id===id);if(!e)return;const p=document.createElement('p');p.textContent='💧 Nước '+Math.round(e.thirst??80)+'% · '+purposeNames[mindFor(e).type];$('selection').append(p);};
renderKingdoms=function(){mindOld.renderKingdoms();const box=$('kingdom-list');for(const k of kingdoms){const people=members(k.id);if(!people.length)continue;const detail=document.createElement('p');detail.className='kingdom-detail';const king=people.find(e=>e.id===k.king);detail.textContent='♛ '+k.name+' · Chủ tộc '+raceNames[kingdomRace(k.id)]+' · Vua '+(king?.name||'chờ kế vị')+' · '+(laws.autoWar?'Có thể tự tuyên chiến':'Ngoại giao do bạn quyết định');box.append(detail);for(const v of villages.filter(v=>v.kingdom===k.id)){const progress=document.createElement('p');progress.className='kingdom-detail';progress.textContent=v.name+' · Nước '+Math.floor(v.water??100)+' · Tri thức '+Math.floor(v.knowledge)+'/'+([30,110,260,520][v.tech]||520)+' · '+techRequirement(v);box.append(progress);}}};
snapshot=function(){initializeMindState();return{...mindOld.snapshot(),version:7,relations:JSON.parse(JSON.stringify(relations))};};
restore=function(input){const d=JSON.parse(JSON.stringify(input)),version=d?.version;if(version===7){const valid=n=>typeof n==='number'&&Number.isFinite(n)&&n>=0&&n<=1e10;if(!d.entities?.every(e=>e.kind!=='human'||valid(e.thirst)&&e.thirst<=100)||!d.villages?.every(v=>Object.hasOwn(raceNames,v.culture)&&valid(v.water)&&v.water<=200&&valid(v.settledAt))||!d.relations||typeof d.relations!=='object'||Array.isArray(d.relations)||Object.keys(d.relations).length>4950||!Object.entries(d.relations).every(([key,v])=>/^\d+:\d+$/.test(key)&&v&&valid(v.truceUntil)))throw Error('Dữ liệu sinh tồn hoặc ngoại giao không hợp lệ.');d.version=6;}mindOld.restore(d);resetMinds();if(version===7)relations=d.relations;else laws.autoWar=true;initializeMindState();syncLawControls();};
if(simTime<1&&calendarTime<1)for(const [i,v] of villages.entries()){v.culture=['human','elf','orc'][i%3];for(const e of humans().filter(e=>e.village===v.id)){e.race=v.culture;e.traits=[e.race==='elf'?'longlife':e.race==='orc'?'strong':'wise'];}}
initializeMindState();laws.autoWar=true;syncLawControls();
$('kingdom-open').onclick=()=>{renderKingdoms();$('kingdom-dialog').showModal();};
const mindReadState=window.mamWorld.getState;
window.mamWorld={...window.mamWorld,newWorld:(...a)=>newWorld(...a),simulate:dt=>simulate(dt),ecology:()=>ecology(),applyTool:(...a)=>applyTool(...a),snapshot:()=>snapshot(),restore:d=>restore(d),getCivilizations:()=>({kingdoms:kingdoms.map(k=>({id:k.id,name:k.name,race:kingdomRace(k.id),king:k.king,population:members(k.id).length})),wars:JSON.parse(JSON.stringify(wars)),villages:villages.map(v=>({id:v.id,tech:v.tech,knowledge:v.knowledge,water:v.water,needs:techRequirement(v)}))}),getState:()=>({...mindReadState(),autoWar:laws.autoWar}),getIntent:id=>{const e=entities.find(e=>e.id===id);return e?{...mindFor(e),goal:mindFor(e).goal&&{...mindFor(e).goal}}:null;}};
if(document.modelContext?.registerTool)try{Promise.resolve(document.modelContext.registerTool({name:'read_civilization_progress',description:'Read kingdoms, kings, wars and resource requirements for the next civilization stage.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>window.mamWorld.getCivilizations()})).catch(()=>{});}catch{}
